# Shared environment for the cached-source probe. Source from anywhere.
# THIRDPARTY_CP is a file listing the third-party classpath (Spark and its closure). It overrides
# the one generated by common.sh.
. "$(dirname "${BASH_SOURCE[0]}")/../common.sh"
SPIKE=$W/.local/work/issue/2832_41-42_decimal-and-annotations/spikes/cached-source
export THIRDPARTY_CP=${THIRDPARTY_CP:-$(thirdparty_cp)}
export SPIKE
# LOCK serialises benchmark runs; point it at one file to share it between checkouts.
export LOCK=${LOCK:-$W/.local/bench.lock}
